insert into public.stores(id,name,category,description,owner_email,image,address,opening_hours,translations,online_ordering,delivery_enabled,pickup_enabled,active,is_open,auto_hours,is_example,text_only,delivery_fee,minimum_order,areas,delivery_time) values('e5617996-0dde-5ec4-b602-7d6a317ae244','صيدلية داريا — مثال','shop','صفحة تعريفية بصيدلية تعرض معلومات عن المستلزمات الطبية ومنتجات العناية الشخصية. للاستفسار عن توفر أي صنف، يُراجع المحل مباشرة. لا توجد طلبات عبر الموقع. مثال توضيحي، والصورة تعبّر عن النشاط وليست صورة محل فعلي.','abdallrahim.birekdar@gmail.com','https://abdallrahimbirekdar-rgb.github.io/beep-beep-daraya/images/examples/pharmacy.webp','داريا، سوريا — العنوان التفصيلي يُضاف من صاحب المحل؛ هذا مثال وليس محلاً فعلياً.','{}'::jsonb,'{"tr": {"name": "Daraya Eczanesi — Örnek", "description": "Eczane, tıbbi malzemeler ve kişisel bakım hakkında tanıtım sayfası. Ürün bulunabilirliğini mağazada sorun. İnternet üzerinden sipariş yok. Örnek sayfa; fotoğraf yalnızca faaliyet alanını gösterir.", "address": "Daraya, Suriye — gerçek adres daha sonra eklenecek."}, "de": {"name": "Apotheke Daraya — Beispiel", "description": "Informationsseite für eine Apotheke, medizinischen Bedarf und Körperpflege. Die Verfügbarkeit bitte vor Ort erfragen. Keine Online-Bestellungen. Beispielseite; das Foto zeigt nur die Tätigkeit.", "address": "Daraya, Syrien — die tatsächliche Adresse wird später ergänzt."}}'::jsonb,false,false,false,true,false,false,true,true,0,0,'{}'::text[],'') on conflict(id) do nothing;
insert into public.stores(id,name,category,description,owner_email,image,address,opening_hours,translations,online_ordering,delivery_enabled,pickup_enabled,active,is_open,auto_hours,is_example,text_only,delivery_fee,minimum_order,areas,delivery_time) values('c897922c-7052-51f1-a767-b72a1ea9596b','مكتب محامي داريا — مثال','shop','مكتب محاماة للاستشارات القانونية ومراجعة العقود والمعاملات. تُحدّد طبيعة الخدمة وأتعابها والموعد عند التواصل مع المكتب. هذه صفحة تعريفية فقط. مثال توضيحي، والصورة تعبّر عن النشاط وليست صورة محل فعلي.','abdallrahim.birekdar@gmail.com','https://abdallrahimbirekdar-rgb.github.io/beep-beep-daraya/images/examples/lawyer.webp','داريا، سوريا — العنوان التفصيلي يُضاف من صاحب المحل؛ هذا مثال وليس محلاً فعلياً.','{}'::jsonb,'{"tr": {"name": "Daraya Avukatlık Bürosu — Örnek", "description": "Hukuki danışmanlık ve sözleşme incelemesi için büro tanıtımı. Hizmet, ücret ve randevu doğrudan büroyla belirlenir. Örnek sayfa; fotoğraf yalnızca faaliyet alanını gösterir.", "address": "Daraya, Suriye — gerçek adres daha sonra eklenecek."}, "de": {"name": "Anwaltsbüro Daraya — Beispiel", "description": "Büro für Rechtsberatung und Prüfung von Verträgen. Leistung, Honorar und Termin werden direkt mit dem Büro vereinbart. Beispielseite; das Foto zeigt nur die Tätigkeit.", "address": "Daraya, Syrien — die tatsächliche Adresse wird später ergänzt."}}'::jsonb,false,false,false,true,false,false,true,true,0,0,'{}'::text[],'') on conflict(id) do nothing;
